# @param {"type": "text", "default": "long battery life and fast charging", "label": "Capability to search for"}
kb_query = "long battery life and fast charging"
# @param {"type": "dropdown", "options": ["Electronics", "Beauty", "Home", "Sports", "Clothing", "Toys"], "default": "Electronics", "label": "Restrict to category"}
kb_category = "Electronics"
# @param {"type": "slider", "min": 1, "max": 10, "step": 1, "default": 5, "label": "Chunks to retrieve (top_k)"}
kb_top_k = 5

# Simple metadata filter: {field: value} → server-side equality match on the doc's
# sidecar metadata. Multiple keys would AND together (e.g. category AND brand).
chunks = read_bedrock_kb(kb_query, filter={"category": kb_category}, top_k=kb_top_k)
print(f"{len(chunks)} chunk(s) for '{kb_query}' within category='{kb_category}'")
if len(chunks):
    print(f"score range: {chunks['score'].min():.3f} – {chunks['score'].max():.3f}")
# metadata is a dict per chunk — surface a couple of fields to see the filter worked
if len(chunks):
    chunks_view = chunks.assign(
        product=chunks['metadata'].apply(lambda m: m.get('product_name', '')),
        category=chunks['metadata'].apply(lambda m: m.get('category', '')),
    )
    chunks_view = chunks_view[['product', 'category', 'score', 'text', 'source_uri']]
chunks_view if len(chunks) else chunks

# @param {"type": "slider", "min": 3.0, "max": 5.0, "step": 0.1, "default": 4.0, "label": "Min average rating"}
kb_min_rating = 4.0

# Raw Bedrock filter: numeric comparison + AND of two clauses. The helper sees the
# operator key ('andAll'/'greaterThanOrEquals') and forwards it unchanged.
rating_filter = {
    "andAll": [
        {"equals": {"key": "category", "value": kb_category}},
        {"greaterThanOrEquals": {"key": "rating_avg", "value": kb_min_rating}},
    ]
}
top_rated_chunks = read_bedrock_kb(kb_query, filter=rating_filter, top_k=kb_top_k)
print(f"{len(top_rated_chunks)} chunk(s) in {kb_category} with rating_avg >= {kb_min_rating}")
if len(top_rated_chunks):
    top_rated_view = top_rated_chunks.assign(
        product=top_rated_chunks['metadata'].apply(lambda m: m.get('product_name', '')),
        rating=top_rated_chunks['metadata'].apply(lambda m: m.get('rating_avg')),
    )[['product', 'rating', 'score', 'text']]
else:
    print("No chunks matched — lower the rating slider or widen the query.")
top_rated_view if len(top_rated_chunks) else top_rated_chunks
